const input = [
  {
    "text": "```json\n{\n  \"is_inquiry\": true,\n  \"reason\": \"availability request for June-July 2026 dates\"\n}\n```"
  }
];

// Parse each item and return as array of objects
const results = input.map(item => {
  const cleaned = item.text.replace(/```json\n?|\n?```/g, "").trim();
  return JSON.parse(cleaned);
});

return results;
// Returns: [{ is_inquiry: true, reason: "availability request for June-July 2026 dates" }]

const subject = ($input.item.json.subject || '').toLowerCase();
const body = ($input.item.json.bodyPreview || '').toLowerCase();
const fromEmail = ($input.item.json.from_emailaddress || '').toLowerCase();
const haystack = subject + ' ' + body;

// Guard 1: skip auto-replies
if (/auto.?reply|out of office|abwesenheit|fuori sede|automatic reply|autoresponder/i.test(subject)) {
  return { json: { ...$input.item.json, is_inquiry: false, filterReason: 'auto-reply' } };
}

// Guard 2: skip our own outgoing mail
if (fromEmail.includes('grueter-residence.com') || fromEmail.includes('grueteroffice.com')) {
  return { json: { ...$input.item.json, is_inquiry: false, filterReason: 'self-sent' } };
}

// Main keyword check
const keywords = [
  'available', 'availability', 'book', 'booking', 'stay', 'dates', 'nights',
  'villa', 'finca', 'residence', 'shoot', 'event', 'rental', 'rent',
  'quote', 'price', 'rate', 'reservation', 'inquiry', 'enquiry',
  'check-in', 'check in', 'guests', 'commission', 'production',
  'g residence', 'grueter', 'colibri', 'cielo azul'
];

const matchedKeywords = keywords.filter(k => haystack.includes(k));
const is_inquiry = matchedKeywords.length > 0;

return {
  json: {
    ...$input.item.json,
    is_inquiry,
    matchedKeywords,
    matchScore: matchedKeywords.length,
    filterReason: is_inquiry ? 'matched' : 'no-keywords'
  }
};

const item = $input.item.json;

// Find the AI output regardless of node shape
const raw = item.output ?? item.text ?? item.choices?.[0]?.message?.content ?? '';

// Strip markdown fences if present
const cleaned = String(raw).trim()
  .replace(/^```(?:json)?\s*\n?/i, '')
  .replace(/\n?```\s*$/, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  // Pull through original email + flag for escalation
  const orig = $('Normalize Email').item.json;
  return {
    json: {
      ...orig,
      classification: null,
      parseFailed: true,
      rawAiResponse: raw,
      shouldEscalate: true,
      escalateReason: 'AI returned invalid JSON',
      decision: 'escalate'
    }
  };
}

// Pull through original email fields
const orig = $('Normalize Email').item.json;

// Compute nights from dates if AI didn't or to verify
let computedNights = parsed.nights ?? null;
if (parsed.check_in && parsed.check_out) {
  const ms = new Date(parsed.check_out) - new Date(parsed.check_in);
  computedNights = Math.max(0, Math.round(ms / 86400000));
}

let checkInDow = parsed.check_in_dow;
let checkOutDow = parsed.check_out_dow;

if (parsed.check_in) {
  const dows = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  checkInDow = dows[new Date(parsed.check_in).getUTCDay()];
}
if (parsed.check_out) {
  const dows = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
  checkOutDow = dows[new Date(parsed.check_out).getUTCDay()];
}

const isSameDay = parsed.check_in && parsed.check_in === parsed.check_out;

return {
  json: {
    // Original email passthrough
    subject: orig.subject,
    fromEmail: orig.from_emailaddress,
    fromName: orig.fromName,
    bodyPreview: orig.bodyPreview,
    bodyHtml: orig.bodyHtml,
    internetMessageId: orig.internetMessageId,
    conversationId: orig.conversationId,
    references: orig.references,
    receivedDate: orig.receivedDate,
    to: orig.to,

    // Classification (flattened)
    isInquiry: parsed.is_inquiry,
    intent: parsed.intent,
    propertyName: parsed.property_name,
    checkIn: parsed.check_in,
    checkOut: parsed.check_out,
    nights: computedNights,
    checkInDow: parsed.check_in_dow,
    checkOutDow: parsed.check_out_dow,
    guests: parsed.guests,
    isB2bAgent: parsed.is_b2b_agent,
    clientQuotedRate: parsed.client_quoted_rate,
    askedForServices: parsed.asked_for_services,
    askedForPaymentTerms: parsed.asked_for_payment_terms,
    askedForFullDetails: parsed.asked_for_full_details,
    questionsInEmail: parsed.questions_in_email,
    language: parsed.language,
    confidence: parsed.confidence,
    missingFields: parsed.missing_fields || [],
    aiNotes: parsed.notes,
    isSameDay,

    // Routing
    parseFailed: false,
    shouldEscalate: parsed.confidence === 'low' || !parsed.is_inquiry || parsed.intent === 'not_an_inquiry'
  }
};

// Pull the AI's extracted property name (could be null, fuzzy, or with extra suffix like "Villa Colibri 5")
const aiPropertyName = ($('Parse Classification').item.json.propertyName || '').toLowerCase().trim();

// Get all property rows returned by the previous node (filtered by inbox already)
const propertyRows = $input.all().map(item => item.json);

// Helper: normalize for comparison (lowercase, trim, collapse whitespace)
const normalize = (s) => (s || '')
  .toLowerCase()
  .normalize('NFD')          // decompose accents
  .replace(/[\u0300-\u036f]/g, '')  // strip accent marks
  .trim()
  .replace(/\s+/g, ' ');

// Helper: does the AI's property name contain or get contained by any candidate string?
const matches = (aiName, candidate) => {
  const a = normalize(aiName);
  const c = normalize(candidate);
  if (!a || !c) return false;
  // bidirectional substring match — handles "Villa Colibri 5" vs "Villa Colibrí" both ways
  return a.includes(c) || c.includes(a);
};

// Try to find a matching row
let matchedProperty = null;
let matchReason = null;

for (const row of propertyRows) {
  // First try: exact-ish match on property_name
  if (matches(aiPropertyName, row.property_name)) {
    matchedProperty = row;
    matchReason = 'name_match';
    break;
  }

  // Second try: match against any alias (aliases column is comma-separated)
  const aliases = (row.aliases || '').split(',').map(a => a.trim()).filter(Boolean);
  for (const alias of aliases) {
    if (matches(aiPropertyName, alias)) {
      matchedProperty = row;
      matchReason = 'alias_match';
      break;
    }
  }
  if (matchedProperty) break;
}

// Pull through all the original classification data + the matched property
const classification = $('Parse Classification').item.json;

if (matchedProperty) {
  return [{
    json: {
      ...classification,
      // Matched property fields, prefixed for clarity
      propertyId: matchedProperty.property_id,
      propertyCanonicalName: matchedProperty.property_name,
      propertyInbox: matchedProperty.inbox,
      propertyChannel: matchedProperty.channel,
      propertyIcalUrl: matchedProperty.ical_url,
      acceptsOvernight: String(matchedProperty.accepts_overnight).toUpperCase() === 'TRUE',
      acceptsEvents: String(matchedProperty.accepts_events).toUpperCase() === 'TRUE',
      currency: matchedProperty.currency,
      securityDeposit: matchedProperty.security_deposit,
      templateSet: matchedProperty.template_set,
      // Match metadata
      propertyMatched: true,
      matchReason,
      matchedAgainst: aiPropertyName
    }
  }];
}

// Common known properties from the OTHER inbox — used to detect routing errors
const OTHER_INBOX_HINTS = {
  'office@grueter-residence.com': ['villa colibri', 'colibrí', 'finca', 'cielo azul'],
  'info@grueteroffice.com': ['g residence', 'grueter', 'gruter']
};

const currentInbox = (classification.to || '').toLowerCase();
const otherInboxKeywords = OTHER_INBOX_HINTS[
  Object.keys(OTHER_INBOX_HINTS).find(k => currentInbox.includes(k.split('@')[0])) || ''
] || [];

const looksLikeWrongInbox = otherInboxKeywords.some(kw => 
  aiPropertyName.includes(kw)
);


// No match — pull through everything for the escalation path to use
return [{
  json: {
    ...classification,
    propertyMatched: false,
    matchReason: 'no_match',
    matchedAgainst: aiPropertyName,
    candidatesChecked: propertyRows.map(r => r.property_name),
    shouldEscalate: true,
    escalateReason: looksLikeWrongInbox 
      ? 'wrong_inbox_likely' 
      : 'property_not_recognized',
    routingHint: looksLikeWrongInbox 
      ? 'This inquiry mentions a property managed by your other inbox. Likely a sender routing error.' 
      : null
  }
}];

