  if (checkInDow !== 'Sat') {
    violations.push({
      type: 'sat_to_sat_check_in',
      detail: `Check-in is ${checkInDow}, but July/August requires Saturday check-in.`
    });
  }
  if (checkOutDow !== 'Sat') {
    violations.push({
      type: 'sat_to_sat_check_out',
      detail: `Check-out is ${checkOutDow}, but July/August requires Saturday check-out.`
    });
  }
  if (nights !== 7) {
    violations.push({
      type: 'sat_to_sat_duration',
      detail: `Stay is ${nights} nights, but July/August requires exactly 7 nights.`
    });
  }
}

// Rule 2: Minimum nights
const minNights = isJulAug ? 7 : 4;
if (nights < minNights) {
  violations.push({
    type: 'min_nights',
    detail: `Stay is ${nights} nights, minimum for this period is ${minNights} nights.`
  });
}

const rulesViolated = violations.length > 0;

// ─── Pull through everything + the rule-check verdict ───
return [{
  json: {
    ...data,
    // Overwrite with computed values (they are the truth)
    checkInDow,
    checkOutDow,
    nights,
    // Rule check verdict
    rulesViolated,
    violations,
    minNightsRequired: minNights,
    requiresSatToSat,
    // If violated, escalation hint for downstream nodes
    shouldEscalate: rulesViolated || data.shouldEscalate === true,
    escalateReason: rulesViolated 
      ? (violations[0].type.startsWith('sat_to_sat') ? 'sat_to_sat_required' : 'min_nights_not_met')
      : data.escalateReason
  }
}];

// Get all upstream data
const data = $input.first().json;

// ─── Recompute date-derived fields from ground truth ───
const checkIn = new Date(data.checkIn + (data.checkIn.includes('T') ? '' : 'T00:00:00Z'));
const checkOut = new Date(data.checkOut + (data.checkOut.includes('T') ? '' : 'T00:00:00Z'));

const dows = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const checkInDow = dows[checkIn.getUTCDay()];
const checkOutDow = dows[checkOut.getUTCDay()];

const ms = checkOut - checkIn;
const nights = Math.max(0, Math.round(ms / 86400000));

// ─── Determine the season for the check-in date ───
const month = checkIn.getUTCMonth() + 1;  // 1-12
const isJulAug = (month === 7 || month === 8);

// ─── Apply the rules ───
const violations = [];

// Rule 1: Saturday-to-Saturday in July & August (overnight properties only)
const requiresSatToSat = isJulAug && data.acceptsOvernight === true;

if (requiresSatToSat) {
  if (checkInDow !== 'Sat') {
    violations.push({
      type: 'sat_to_sat_check_in',
      detail: `Check-in is ${checkInDow}, but July/August requires Saturday check-in.`
    });
  }
  if (checkOutDow !== 'Sat') {
    violations.push({
      type: 'sat_to_sat_check_out',
      detail: `Check-out is ${checkOutDow}, but July/August requires Saturday check-out.`
    });
  }
  if (nights !== 7) {
    violations.push({
      type: 'sat_to_sat_duration',
      detail: `Stay is ${nights} nights, but July/August requires exactly 7 nights.`
    });
  }
}

// Rule 2: Minimum nights
const minNights = isJulAug ? 7 : 4;
if (nights < minNights) {
  violations.push({
    type: 'min_nights',
    detail: `Stay is ${nights} nights, minimum for this period is ${minNights} nights.`
  });
}

const rulesViolated = violations.length > 0;

// ─── Pull through everything + the rule-check verdict ───
return [{
  json: {
    ...data,
    // Overwrite with computed values (they are the truth)
    checkInDow,
    checkOutDow,
    nights,
    // Rule check verdict
    rulesViolated,
    violations,
    minNightsRequired: minNights,
    requiresSatToSat,
    // If violated, escalation hint for downstream nodes
    shouldEscalate: rulesViolated || data.shouldEscalate === true,
    escalateReason: rulesViolated 
      ? (violations[0].type.startsWith('sat_to_sat') ? 'sat_to_sat_required' : 'min_nights_not_met')
      : data.escalateReason
  }
}];

// Pull all pricing rows that came from Fetch Pricing Rows
const pricingRows = $input.all().map(item => item.json);

// Pull the validated booking data from upstream
const data = $('Booking Rules Check1').item.json;

// ─── Defensive: skip pricing for location-only properties ───
// Same-day shoots / events have bespoke pricing; we don't auto-calculate.
if (data.acceptsOvernight === false) {
  return [{
    json: {
      ...data,
      totalPrice: null,
      pricePerNightAvg: null,
      priceBreakdown: [],
      priceCalculated: false,
      pricingError: 'event_pricing_bespoke',
      pricingNote: 'Event/shoot pricing requires manual quote — not auto-calculated.'
    }
  }];
}

// ─── Defensive: ensure we have pricing data to work with ───
if (!pricingRows.length) {
  return [{
    json: {
      ...data,
      totalPrice: null,
      pricePerNightAvg: null,
      priceBreakdown: [],
      priceCalculated: false,
      pricingError: 'no_pricing_rows_found',
      shouldEscalate: true,
      escalateReason: 'no_pricing_data',
      pricingNote: `No pricing rows found in Sheet for ${data.propertyId}.`
    }
  }];
}

// ─── Walk night-by-night through the stay ───
const checkIn = new Date(data.checkIn + 'T00:00:00Z');
const checkOut = new Date(data.checkOut + 'T00:00:00Z');

let total = 0;
const breakdown = [];
const unmatchedNights = [];

// Iterate one night at a time. Each iteration represents ONE night booked.
// (Check-out day is exclusive — guest doesn't pay for the day they leave.)
for (let d = new Date(checkIn); d < checkOut; d.setUTCDate(d.getUTCDate() + 1)) {
  const month = d.getUTCMonth() + 1;
  const day = d.getUTCDate();
  const dateStr = d.toISOString().slice(0, 10);

  // Find the pricing row that covers this specific date
  const matchedRow = pricingRows.find(r => {
    const sm = Number(r.start_month);
    const sd = Number(r.start_day);
    const em = Number(r.end_month);
    const ed = Number(r.end_day);

    // Year-wrap case (e.g., Christmas/NYE: Dec 23 → Jan 3)
    // start_month > end_month means the range crosses Dec→Jan
    if (sm > em) {
      const afterStart = (month > sm) || (month === sm && day >= sd);
      const beforeEnd = (month < em) || (month === em && day <= ed);
      return afterStart || beforeEnd;
    }

    // Normal case: range stays within one year
    const afterStart = (month > sm) || (month === sm && day >= sd);
    const beforeEnd = (month < em) || (month === em && day <= ed);
    return afterStart && beforeEnd;
  });

  if (matchedRow) {
    const nightlyRate = Number(matchedRow.price_per_night);
    if (isNaN(nightlyRate)) {
      unmatchedNights.push({ date: dateStr, reason: 'rate_is_not_a_number' });
    } else {
      total += nightlyRate;
      breakdown.push({
        date: dateStr,
        period: matchedRow.period_label,
        rate: nightlyRate
      });
    }
  } else {
    unmatchedNights.push({ date: dateStr, reason: 'no_period_matches' });
  }
}

// ─── Handle case where some nights couldn't be priced ───
if (unmatchedNights.length > 0) {
  return [{
    json: {
      ...data,
      totalPrice: null,
      pricePerNightAvg: null,
      priceBreakdown: breakdown,
      priceCalculated: false,
      pricingError: 'incomplete_pricing_coverage',
      unmatchedNights,
      shouldEscalate: true,
      escalateReason: 'pricing_gap',
      pricingNote: `${unmatchedNights.length} of ${data.nights} nights could not be priced. Sheet may have a gap in date coverage.`
    }
  }];
}

// ─── Success: return the total + breakdown ───
const pricePerNightAvg = data.nights > 0 
  ? Math.round(total / data.nights) 
  : 0;

return [{
  json: {
    ...data,
    totalPrice: total,
    pricePerNightAvg,
    priceBreakdown: breakdown,
    priceCalculated: true,
    pricingError: null,
    currency: data.currency || 'EUR'
  }
}];

const data = $input.first().json;

// ─── Extract the inputs we need to decide on ───
const acceptsOvernight = data.acceptsOvernight === true;
const intent = data.intent;
const available = data.available;
const priceCalculated = data.priceCalculated;
const pricingError = data.pricingError;
const rulesViolated = data.rulesViolated === true;
const violations = data.violations || [];
const askedDetails = data.askedForFullDetails === true ||
                     (data.askedForServices === true && data.askedForPaymentTerms === true);

// Booking-type intents (vs holiday-stay)
const isEventIntent = ['photo_shoot', 'video_shoot', 'event_rental', 'mixed'].includes(intent);
const isHolidayStay = intent === 'holiday_stay';

// ─── Detect rule-violation type (when applicable) ───
// First Sat-Sat violation takes precedence — it's the bigger ask of the guest
const hasSatToSatViolation = violations.some(v => 
  v.type && v.type.startsWith('sat_to_sat')
);
const hasMinNightsViolation = violations.some(v => 
  v.type === 'min_nights'
);

let scenario;
let scenarioReason;
let templateSetOverride = null;  // some scenarios use the 'shared' template_set

// ─── Decision tree ───

// Case 1: Property is unavailable for the requested dates
// (Wins over rule violations — no point asking for Sat-Sat dates if the dates are taken anyway)
if (available === false) {
  scenario = 'unavailable';
  scenarioReason = 'iCal conflict on requested dates';
}

// Case 2: Sat-Sat rule violated (Jul/Aug, overnight property)
// Per scope: ask the guest for valid Sat-Sat dates. Don't escalate yet.
else if (rulesViolated && hasSatToSatViolation) {
  scenario = 'sat_to_sat_required';
  scenarioReason = 'Jul/Aug requires Sat-Sat — asking guest to revise dates';
  templateSetOverride = 'shared';
}

// Case 3: Min-nights rule violated
else if (rulesViolated && hasMinNightsViolation) {
  scenario = 'min_nights_not_met';
  scenarioReason = `Below minimum stay (${data.minNightsRequired} nights required) — asking guest to extend or flex`;
  templateSetOverride = 'shared';
}

// Case 4: Rules violated for some other reason — fall back to escalation
else if (rulesViolated) {
  scenario = 'escalate';
  scenarioReason = `Rules violated but type unrecognized: ${violations.map(v => v.type).join(', ')}`;
}

// Case 5: Location-only property + holiday stay request
else if (!acceptsOvernight && isHolidayStay) {
  scenario = 'not_overnight';
  scenarioReason = 'Location-only property, guest asked for holiday stay';
}

// Case 6: Event/shoot intent (any property)
else if (isEventIntent) {
  scenario = 'event_inquiry';
  scenarioReason = 'Event or shoot request — needs production details before quote';
}

// Case 7: Overnight + holiday stay + pricing failed
else if (acceptsOvernight && isHolidayStay && priceCalculated === false) {
  scenario = 'available_no_rate';
  scenarioReason = `Pricing not auto-calculable: ${pricingError || 'unknown'}`;
}

// Case 8: Overnight + holiday stay + pricing OK + asked for full details
else if (acceptsOvernight && isHolidayStay && priceCalculated === true && askedDetails) {
  scenario = 'available_detailed';
  scenarioReason = 'Available + rate calculated + guest asked for services/payment terms';
}

// Case 9: Overnight + holiday stay + pricing OK + just asked "is it free?"
else if (acceptsOvernight && isHolidayStay && priceCalculated === true) {
  scenario = 'available_simple';
  scenarioReason = 'Available + rate calculated + guest asked simple question only';
}

// Case 10: Anything we didn't anticipate — escalate
else {
  scenario = 'escalate';
  scenarioReason = `Unhandled combination: overnight=${acceptsOvernight}, intent=${intent}, available=${available}, priceCalculated=${priceCalculated}`;
}

// ─── Compose the template_id we'll look up next ───
const templateSet = templateSetOverride || data.templateSet || 'shared';
const templateId = `${templateSet}_${scenario}`;

// ─── Return passthrough + scenario decision ───
return [{
  json: {
    ...data,
    scenario,
    scenarioReason,
    templateId,
    templateSetUsed: templateSet,
    shouldEscalate: scenario === 'escalate' || data.shouldEscalate === true,
    escalateReason: scenario === 'escalate' 
      ? (data.escalateReason || 'unhandled_scenario')
      : data.escalateReason
  }
}];

// Pull what came back from Fetch Template
const templateRow = $input.first().json;

// Pull the upstream context (everything we've established before)
const upstream = $('Build Scenario1').item.json;

// ─── Did the lookup find a row? ───
// When the Sheets node finds nothing, the row will lack expected fields
const templateFound = !!(templateRow && templateRow.template_id && templateRow.body);

if (!templateFound) {
  // No matching template — this means our Build Scenario produced a templateId
  // that doesn't exist in the Sheet. Real bug: either Sheet is missing the row,
  // or the templateId formatting drifted. Escalate to humans.
  return [{
    json: {
      ...upstream,
      templateFound: false,
      templateSubjectRaw: null,
      templateBodyRaw: null,
      templateLanguage: null,
      shouldEscalate: true,
      escalateReason: 'template_missing',
      templateMissingNote: `No template found for templateId="${upstream.templateId}" language="${upstream.language || 'en'}". Add this row to the Templates sheet.`
    }
  }];
}

// ─── Found it — pass forward with raw template content ───
return [{
  json: {
    ...upstream,
    templateFound: true,
    templateSubjectRaw: templateRow.subject || '',
    templateBodyRaw: templateRow.body || '',
    templateLanguage: templateRow.language || 'en',
    templateMatchedId: templateRow.template_id
  }
}];

const data = $input.first().json;

// ─── Pull the raw template content ───
const subjectRaw = data.templateSubjectRaw || '';
const bodyRaw = data.templateBodyRaw || '';

// ─── Compute derived values for substitution ───

// Guest first name — extract from "daytor ramaj" → "daytor"
// Capitalize for politeness even if the email had it lowercase
const fromName = (data.fromName || '').trim();
const guestFirstName = fromName 
  ? fromName.split(/\s+/)[0].replace(/^./, c => c.toUpperCase())
  : 'there';  // fallback when sender has no name in their email signature

// Property name — prefer canonical from the Properties sheet, not the AI's extraction
const propertyName = data.propertyCanonicalName || data.propertyName || 'the property';

// Price formatting — European convention: €35.805 (period as thousands separator)
// Or skip entirely if no price was calculated
let priceFormatted = '';
if (data.priceCalculated === true && typeof data.totalPrice === 'number') {
  priceFormatted = '€' + data.totalPrice.toLocaleString('de-DE', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  });
}

// iCal URL — for unavailable templates that include the link
const icalUrl = data.propertyIcalUrl || '';

// Nights and min_nights — for the min_nights template
const nights = data.nights ?? '';
const minNights = data.minNightsRequired ?? '';

// Original subject — for "Re: {{original_subject}}" style replies
let originalSubject = data.subject || 'Inquiry';
// Strip existing Re: prefixes so we don't accumulate "Re: Re: Re:"
originalSubject = originalSubject.replace(/^(Re:\s*)+/i, '');

// ─── Substitution map ───
const tokens = {
  guest_first_name: guestFirstName,
  property_name: propertyName,
  price: priceFormatted,
  ical_url: icalUrl,
  nights: nights,
  min_nights: minNights,
  original_subject: originalSubject,
  // Add more here as templates evolve
};

// ─── Substitute and track which tokens fired ───
const placeholdersUsed = [];
const placeholdersMissing = [];

function substitute(text, tokenMap) {
  return text.replace(/\{\{\s*(\w+)\s*\}\}/g, (full, key) => {
    if (key in tokenMap) {
      const value = tokenMap[key];
      if (value === '' || value === null || value === undefined) {
        placeholdersMissing.push(key);
        return full;  // leave the {{token}} in place so it's visible the value was missing
      }
      placeholdersUsed.push(key);
      return String(value);
    }
    // Unknown token — leave in place, flag it
    placeholdersMissing.push(key);
    return full;
  });
}

const replySubject = substitute(subjectRaw, tokens);
const replyBody = substitute(bodyRaw, tokens);

// ─── HTML version of the body for email clients that prefer it ───
// Convert plain text paragraphs to <p> blocks. Templates use \n\n for paragraph breaks.
const replyBodyHtml = replyBody
  .split(/\n\s*\n/)
  .map(p => `<p>${p.trim().replace(/\n/g, '<br>')}</p>`)
  .join('\n');

// ─── Detect critical missing placeholders (escalation triggers) ───
// If a CRITICAL token is missing in a draft, escalate instead of sending broken text
const criticalIfBlank = ['property_name', 'guest_first_name'];
const criticalMissing = [...new Set(placeholdersMissing)].filter(p => 
  criticalIfBlank.includes(p)
);

// Price is critical only for templates that explicitly use it
const usedPriceToken = /\{\{\s*price\s*\}\}/.test(bodyRaw);
const priceCritical = usedPriceToken && !priceFormatted;

const hasCriticalGap = criticalMissing.length > 0 || priceCritical;

return [{
  json: {
    ...data,
    replySubject,
    replyBody,
    replyBodyHtml,
    placeholdersUsed: [...new Set(placeholdersUsed)],
    placeholdersMissing: [...new Set(placeholdersMissing)],
    hasCriticalPlaceholderGap: hasCriticalGap,
    shouldEscalate: hasCriticalGap || data.shouldEscalate === true,
    escalateReason: hasCriticalGap 
      ? 'critical_placeholder_missing' 
      : data.escalateReason
  }
}];

